package net.civeira.phylax.features.notification.outbox.domain.model;

import java.util.Optional;

import lombok.Builder;
import lombok.Getter;

/**
 * Domain model representing an outbound email ready to be sent.
 */
@Builder
@Getter
public class OutboundMail {

  /** Destination email address where the message will be delivered. */
  private final String recipient;

  /** Email subject line. Null is allowed for channels that do not use a subject. */
  private final String subject;

  /** HTML body of the message. Never null; at minimum contains a plain-text-as-HTML fallback. */
  private final String htmlContent;

  /**
   * Plain-text alternative body. Null when the template does not define a text variant; the
   * dispatch service falls back to {@link #htmlContent} in that case.
   */
  private final String textContent;

  /**
   * Returns the plain-text alternative body wrapped in an {@link Optional}.
   *
   * @return optional plain-text content; empty when no text variant is available
   */
  public Optional<String> getTextContentOptional() {
    return Optional.ofNullable(textContent);
  }

  /**
   * Returns the subject line wrapped in an {@link Optional}.
   *
   * @return optional subject; empty when the message was built without one
   */
  public Optional<String> getSubjectOptional() {
    return Optional.ofNullable(subject);
  }
}
